document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("travel-insurance-form");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=document.getElementById("destination").value,a=parseInt(document.getElementById("duration").value),t=parseInt(document.getElementById("age").value),i=parseFloat(document.getElementById("tripValue").value),r=document.getElementById("coverage").value,o=document.getElementById("activities").value,d=parseInt(document.getElementById("travelers").value);const s={low:1,medium:1.4,high:2.2};let c=1;t>=65?c=2.5:t>=55?c=1.8:t>=45?c=1.4:t>=35&&(c=1.1);const l={basic:1,standard:1.6,comprehensive:2.4},g={none:1,moderate:1.3,extreme:2};let m=1;a>=30?m=.8:a>=14?m=.9:a>=7&&(m=.95);let v=1;d>=4?v=.85:d>=2&&(v=.95);const u=8*s[n]*c*l[r]*g[o]*m*v,b=u*a,p=b*d,h={basic:{medical:1e5,evacuation:5e5,cancellation:0,baggage:0},standard:{medical:25e4,evacuation:1e6,cancellation:i,baggage:2500},comprehensive:{medical:5e5,evacuation:15e5,cancellation:i,baggage:5e3}}[r],$=p/(i*d)*100,f={low:{name:"Low Risk Destination",risk:"Excellent healthcare, stable conditions"},medium:{name:"Medium Risk Destination",risk:"Good healthcare, some regional concerns"},high:{name:"High Risk Destination",risk:"Limited healthcare, elevated risks"}};document.getElementById("travel-insurance-result").innerHTML=`\n      <h3>✈️ Your Travel Insurance Estimate</h3>\n      \n      <div class="insight-cards">\n        <div class="insight-card info">\n          <h6>💰 Total Premium</h6>\n          <div class="big-number">$${Math.round(p).toLocaleString()}</div>\n          <p>${d} traveler(s) for ${a} days<br>\n          $${Math.round(b).toLocaleString()} per person<br>\n          ${$.toFixed(1)}% of trip value</p>\n        </div>\n        \n        <div class="insight-card success">\n          <h6>🏥 Medical Coverage</h6>\n          <div class="big-number">$${h.medical.toLocaleString()}</div>\n          <p>Emergency medical expenses<br>\n          Evacuation: $${h.evacuation.toLocaleString()}<br>\n          ${f[n].name}</p>\n        </div>\n        \n        <div class="insight-card ${"basic"===r?"warning":"info"}">\n          <h6>🛡️ Trip Protection</h6>\n          <div class="big-number">${h.cancellation>0?"$"+h.cancellation.toLocaleString():"Not Covered"}</div>\n          <p>Cancellation/Interruption<br>\n          Baggage: ${h.baggage>0?"$"+h.baggage.toLocaleString():"Not covered"}<br>\n          ${{basic:"Essential medical and evacuation coverage",standard:"Medical, evacuation, and trip protection",comprehensive:"Complete protection with enhanced benefits"}[r]}</p>\n        </div>\n      </div>\n\n      <div style="margin-top: 2rem; padding: 1.5rem; background: #f8f9fa; border-radius: 12px;">\n        <h4>📋 Coverage Breakdown</h4>\n        \n        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-top: 1rem;">\n          <div>\n            <strong>📍 Trip Details:</strong><br>\n            Destination: ${f[n].name}<br>\n            Duration: ${a} days<br>\n            Travelers: ${d} person(s)<br>\n            Age group: ${t<35?"Young adult":t<55?"Middle-aged":t<65?"Mature":"Senior"}<br>\n            Activities: ${o.charAt(0).toUpperCase()+o.slice(1)} risk\n          </div>\n          \n          <div>\n            <strong>💵 Cost Analysis:</strong><br>\n            Daily rate: $${u.toFixed(2)} per person<br>\n            Base rate: $8/day<br>\n            Risk adjustment: ${(s[n]*c*g[o]).toFixed(1)}x<br>\n            Coverage level: ${l[r]}x<br>\n            Discounts applied: ${(100*(1-m)+100*(1-v)).toFixed(0)}%\n          </div>\n        </div>\n        \n        <div style="margin-top: 1.5rem; padding: 1rem; background: white; border-radius: 8px; border-left: 4px solid #2196f3;">\n          <strong>✅ What's Covered:</strong><br>\n          ${"basic"===r?"• Emergency medical treatment and hospitalization<br>• Medical evacuation and repatriation<br>• 24/7 emergency assistance":"standard"===r?"• All basic coverage benefits<br>• Trip cancellation and interruption<br>• Baggage loss and delay protection<br>• Travel delay compensation":"• All standard coverage benefits<br>• Enhanced coverage limits<br>• Additional baggage protection<br>• Rental car coverage<br>• Personal liability protection"}\n        </div>\n        \n        <div style="margin-top: 1rem; padding: 1rem; background: #fff3cd; border-radius: 8px; border-left: 4px solid #ffc107;">\n          <strong>⚠️ Important Notes:</strong><br>\n          • ${f[n].risk}<br>\n          • Pre-existing medical conditions may require additional coverage<br>\n          • ${"none"!==o?"High-risk activities increase premium and may have exclusions":"Standard activities covered"}<br>\n          • Purchase before your first non-refundable trip payment for full benefits\n        </div>\n      </div>\n    `})});